function GlassAnnealingRollerMaker.init() GlassAnnealingRollerMaker.ironStock=18; GlassAnnealingRollerMaker.bronzeStock=14; GlassAnnealingRollerMaker.woodStock=10; GlassAnnealingRollerMaker.leatherStock=8; GlassAnnealingRollerMaker.silverStock=8; GlassAnnealingRollerMaker.goldStock=6; GlassAnnealingRollerMaker.jewelStock=4; GlassAnnealingRollerMaker.pearlStock=4; GlassAnnealingRollerMaker.productStock={}; GlassAnnealingRollerMaker.buildings={}; GlassAnnealingRollerMaker.maker=nil; GlassAnnealingRollerMaker.activeMaking={}; GlassAnnealingRollerMaker.totalProducts=0; GlassAnnealingRollerMaker.dayTimer=0; print("[GlassAnnealingRollerMaker] Royal Glass Annealing Roller Maker System initialized (6 products, 4 buildings)") end
function GlassAnnealingRollerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassAnnealingRollerMaker.maker={name=n or ("Valjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Valjar najet: %s (spretnost: %d)",GlassAnnealingRollerMaker.maker.name,s),"success") end; return true end
function GlassAnnealingRollerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassAnnealingRollerMaker.build(id) local ok,e=GlassAnnealingRollerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassAnnealingRollerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassAnnealingRollerMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassAnnealingRollerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassAnnealingRollerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassAnnealingRollerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassAnnealingRollerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassAnnealingRollerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassAnnealingRollerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassAnnealingRollerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassAnnealingRollerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassAnnealingRollerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassAnnealingRollerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassAnnealingRollerMaker.buildings==0 then return false,"Potrebna valjarna delavnica" end; if not GlassAnnealingRollerMaker.maker then return false,"Potreben valjar" end; return true end
function GlassAnnealingRollerMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassAnnealingRollerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassAnnealingRollerMaker.ironStock=GlassAnnealingRollerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassAnnealingRollerMaker.bronzeStock=GlassAnnealingRollerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassAnnealingRollerMaker.woodStock=GlassAnnealingRollerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassAnnealingRollerMaker.leatherStock=GlassAnnealingRollerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassAnnealingRollerMaker.silverStock=GlassAnnealingRollerMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassAnnealingRollerMaker.goldStock=GlassAnnealingRollerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassAnnealingRollerMaker.jewelStock=GlassAnnealingRollerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassAnnealingRollerMaker.pearlStock=GlassAnnealingRollerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassAnnealingRollerMaker.maker then t=math.max(1,t-math.floor(GlassAnnealingRollerMaker.maker.skill/13)) end; table.insert(GlassAnnealingRollerMaker.activeMaking,{id="glassannealingroller_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassAnnealingRollerMaker.completeMaking(m) local q=1.0+(GlassAnnealingRollerMaker.getQualityBonus()/100); if GlassAnnealingRollerMaker.maker then q=q+(GlassAnnealingRollerMaker.maker.skill/140) end; q=math.min(2.5,q); GlassAnnealingRollerMaker.productStock[m.productType]=(GlassAnnealingRollerMaker.productStock[m.productType] or 0)+m.quantity; GlassAnnealingRollerMaker.totalProducts=GlassAnnealingRollerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassAnnealingRollerMaker.maker then GlassAnnealingRollerMaker.maker.itemsMade=GlassAnnealingRollerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassAnnealingRollerMaker.maker.skill=math.min(100,GlassAnnealingRollerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Valj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassannealingroller.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassAnnealingRollerMaker.update(dt) if not _G.state then return end; GlassAnnealingRollerMaker.dayTimer=GlassAnnealingRollerMaker.dayTimer+dt; if GlassAnnealingRollerMaker.dayTimer>=30 then GlassAnnealingRollerMaker.dayTimer=0; for i=#GlassAnnealingRollerMaker.activeMaking,1,-1 do local m=GlassAnnealingRollerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassAnnealingRollerMaker.completeMaking(m); table.remove(GlassAnnealingRollerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassAnnealingRollerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassAnnealingRollerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassAnnealingRollerMaker.getStats() return {ironStock=GlassAnnealingRollerMaker.ironStock,bronzeStock=GlassAnnealingRollerMaker.bronzeStock,woodStock=GlassAnnealingRollerMaker.woodStock,leatherStock=GlassAnnealingRollerMaker.leatherStock,silverStock=GlassAnnealingRollerMaker.silverStock,goldStock=GlassAnnealingRollerMaker.goldStock,jewelStock=GlassAnnealingRollerMaker.jewelStock,pearlStock=GlassAnnealingRollerMaker.pearlStock,productStock=GlassAnnealingRollerMaker.productStock,numBuildings=#GlassAnnealingRollerMaker.buildings,hasMaker=GlassAnnealingRollerMaker.maker~=nil,makerName=GlassAnnealingRollerMaker.maker and GlassAnnealingRollerMaker.maker.name or "—",makerSkill=GlassAnnealingRollerMaker.maker and GlassAnnealingRollerMaker.maker.skill or 0,activeMaking=#GlassAnnealingRollerMaker.activeMaking,totalProducts=GlassAnnealingRollerMaker.totalProducts} end
